use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut key: Vec<int> = [0]
    let mut lc: Vec<usize> = [0]
    let mut rc: Vec<usize> = [0]
    let mut root: usize = 0
    for line in text.lines() {
        let parts: Vec<string> = line.split(" ").collect()
        let cmd = parts[0]
        if cmd == "insert" || cmd == "contains" || cmd == "delete" {
            let x: int = parts[1].parse().unwrap_or(0)
            let mut cur: usize = root
            let mut par: usize = 0
            let mut left = false
            while cur != 0 && key[cur] != x {
                par = cur
                if x < key[cur] {
                    left = true
                    cur = lc[cur]
                } else {
                    left = false
                    cur = rc[cur]
                }
            }
            if cmd == "contains" {
                if cur != 0 { println("yes") } else { println("no") }
            } else if cmd == "insert" {
                if cur != 0 {
                    println("dup")
                } else {
                    let id = key.len()
                    key.push(x)
                    lc.push(0)
                    rc.push(0)
                    if par == 0 {
                        root = id
                    } else if left {
                        lc[par] = id
                    } else {
                        rc[par] = id
                    }
                    println("ok")
                }
            } else {
                if cur == 0 {
                    println("missing")
                } else {
                    if lc[cur] != 0 && rc[cur] != 0 {
                        let mut sp = cur
                        let mut s = rc[cur]
                        while lc[s] != 0 {
                            sp = s
                            s = lc[s]
                        }
                        key[cur] = key[s]
                        if sp == cur {
                            rc[sp] = rc[s]
                        } else {
                            lc[sp] = rc[s]
                        }
                    } else {
                        let child = if lc[cur] != 0 { lc[cur] } else { rc[cur] }
                        if par == 0 {
                            root = child
                        } else if left {
                            lc[par] = child
                        } else {
                            rc[par] = child
                        }
                    }
                    println("ok")
                }
            }
        } else if cmd == "inorder" {
            if root == 0 {
                println("<empty>")
            } else {
                let mut out: Vec<string> = []
                let mut stack: Vec<usize> = []
                let mut c = root
                while c != 0 || stack.len() > 0 {
                    while c != 0 {
                        stack.push(c)
                        c = lc[c]
                    }
                    let n = stack.pop().unwrap_or(0)
                    out.push("${key[n]}")
                    c = rc[n]
                }
                println(out.join(" "))
            }
        } else if cmd == "height" {
            let mut best = 0
            if root != 0 {
                let mut ns: Vec<usize> = [root]
                let mut ds: Vec<int> = [1]
                while ns.len() > 0 {
                    let n = ns.pop().unwrap_or(0)
                    let d = ds.pop().unwrap_or(0)
                    if d > best { best = d }
                    if lc[n] != 0 {
                        ns.push(lc[n])
                        ds.push(d + 1)
                    }
                    if rc[n] != 0 {
                        ns.push(rc[n])
                        ds.push(d + 1)
                    }
                }
            }
            println("${best}")
        } else if cmd == "min" || cmd == "max" {
            if root == 0 {
                println("empty")
            } else {
                let mut c = root
                if cmd == "min" {
                    while lc[c] != 0 { c = lc[c] }
                } else {
                    while rc[c] != 0 { c = rc[c] }
                }
                println("${key[c]}")
            }
        }
    }
